"use strict";
// Deliberately browser-memory only. No fetch, provider, storage or campaign API.
const $ = id => document.getElementById(id);
const state = {step:0,unlocked:0,brief:"",identity:"",tone:"Sıcak ve samimi",accent:"#c26940",selected:null,cards:[],batch:0,history:[],image:null,editing:null,plan:null};
let fileVersion = 0;
const money = value => new Intl.NumberFormat("tr-TR",{style:"currency",currency:"TRY",maximumFractionDigits:0}).format(value);
function toast(text){$("toast").textContent=text;$("toast").style.display="block";clearTimeout(toast.timer);toast.timer=setTimeout(()=>$("toast").style.display="none",4500);}
function message(text,user=false){const item=document.createElement("div");item.className=`message ${user?"user-message":"assistant-message"}`;item.textContent=text;$("chat-log").append(item);if($("chat-log").children.length>30)$("chat-log").firstElementChild.remove();$("chat-log").scrollTop=$("chat-log").scrollHeight;}
function go(step){if(step>state.unlocked)return;state.step=step;document.querySelectorAll(".step").forEach((el,i)=>el.hidden=i!==step);document.querySelectorAll(".progress button").forEach((el,i)=>{el.disabled=i>state.unlocked;el.classList.toggle("done",i<step);if(i===step)el.setAttribute("aria-current","step");else el.removeAttribute("aria-current");});if(step===3)review();window.scrollTo({top:0,behavior:"smooth"});}
document.querySelectorAll("[data-step]").forEach(el=>el.addEventListener("click",()=>go(Number(el.dataset.step))));
document.querySelectorAll("[data-example]").forEach(el=>el.addEventListener("click",()=>{$("brief").value=el.dataset.example;$("brief").focus();}));
const approachNames=["Ürünün hikâyesi","Bir anın hissi","Merak uyandıran davet"];
const subtitles=["Ürünü ve değerini öne çıkaran, sakin bir anlatım.","Günlük yaşamdan bir hisle yakınlık kuran yaklaşım.","Daha cesur bir dil ve güçlü bir görsel ritim."];
function sampleTitles(){const b=state.brief.toLocaleLowerCase("tr-TR");if(b.includes("kahve"))return ["İyi kahvenin\nküçük hikâyesi.","Bir fincanlık\nmola ver.","YENİ BİR\nMOLA NOKTASI."];if(b.includes("seramik"))return ["Her parçada\nbir dokunuş.","Gündelik anlara\nküçük bir güzellik.","SIRADANIN\nDIŞINA ÇIK."];if(b.includes("atölye")||b.includes("etkinlik"))return ["Bir fikrin\nhikâyesine katıl.","Birlikte üretmenin\ngüzel hâli.","MERAKINA\nYER AÇ."];return ["Fikrinin\nhikâyesini anlat.","Küçük bir an.\nYeni bir başlangıç.","BİR FİKİR.\nYENİ BİR BAKIŞ."];}
function makeBatch(){if(state.cards.length)state.history.push({cards:state.cards,selected:state.selected,batch:state.batch,brief:state.brief});state.batch++;const titles=sampleTitles();state.cards=titles.map((title,i)=>({id:`${state.batch}-${i}`,kind:i,title:state.batch%2===0?["Küçük detaylar.\nBüyük bir his.","Kendine yeni\nbir an ayır.","ŞİMDİ\nBAŞKA BİR BAKIŞ."][i]:title,body:subtitles[i],x:9,y:15,size:30,variant:0,edits:[]}));state.selected=null;state.unlocked=Math.min(state.unlocked,1);renderCards();}
$("brief-form").addEventListener("submit",event=>{event.preventDefault();const value=$("brief").value.trim();if(value.length<12){toast("Neyi tanıtmak istediğini biraz daha anlatır mısın? En az 12 karakter yaz.");return;}const changed=state.brief!==value;if(changed&&state.cards.length){state.history.push({cards:state.cards,selected:state.selected,batch:state.batch,brief:state.brief});state.cards=[];}state.brief=value;$("brief-summary").textContent=value;if(!state.cards.length||changed){makeBatch();state.plan=null;state.unlocked=1;}state.unlocked=Math.max(1,state.unlocked);go(1);message("İsteğini bu çalışmada tuttum. Üç örnek yaratıcı yaklaşım hazır. Gerçek üretimde bu kartlar isteğine özel oluşturulacak; burada deneyimi birlikte inceliyoruz.");});
function illustration(kind){const shapes=[`<rect width="400" height="500" fill="#c4a67c"/><path d="M0 220L400 140V500H0Z" fill="#e3cba2"/><ellipse cx="230" cy="421" rx="155" ry="38" fill="#ac875c" opacity=".4"/><path d="M136 277H300L283 410Q220 450 151 410Z" fill="#f6eee0"/><path d="M300 292C384 274 365 375 292 368" fill="none" stroke="#f6eee0" stroke-width="22"/><ellipse cx="218" cy="279" rx="82" ry="23" fill="#51382b"/><ellipse cx="218" cy="280" rx="62" ry="14" fill="#ae7951"/><path d="M205 210Q164 173 206 139M240 218Q206 189 241 162" fill="none" stroke="#fff9e5" stroke-width="5" opacity=".5"/>`,`<rect width="400" height="500" fill="#284c40"/><circle cx="290" cy="140" r="135" fill="#adc39b"/><path d="M0 355Q150 230 400 360V500H0Z" fill="#637860"/><path d="M70 365H290L267 460H94Z" fill="#d2b286"/><ellipse cx="180" cy="366" rx="110" ry="20" fill="#ebd2a9"/><circle cx="185" cy="350" r="48" fill="#f1e7d4"/><circle cx="185" cy="350" r="32" fill="#5f3b2b"/><path d="M10 0Q60 150 0 280M380 230Q310 290 390 360" fill="none" stroke="#7b976b" stroke-width="27"/>`,`<rect width="400" height="500" fill="#be562f"/><circle cx="340" cy="350" r="175" fill="#eabc72"/><path d="M0 260L220 500H0Z" fill="#742d22"/><path d="M220 245L318 280L263 420L166 385Z" fill="#fff2d1"/><ellipse cx="269" cy="263" rx="51" ry="13" transform="rotate(20 269 263)" fill="#553827"/><path d="M305 300Q385 308 328 361L285 352" fill="none" stroke="#fff2d1" stroke-width="18"/><path d="M35 190L88 206M58 161L83 191M35 225L85 219" stroke="#f4e7c7" stroke-width="5"/>`];return `<svg viewBox="0 0 400 500" aria-hidden="true" xmlns="http://www.w3.org/2000/svg">${shapes[kind]}</svg>`;}
function art(card,editor=false){const node=document.createElement("div");node.className=`art art-${card.kind}`;node.innerHTML=illustration(card.kind);if(state.image){const image=document.createElement("img");image.src=state.image;image.alt="Bu sekmede seçilen sentetik referans görsel";node.append(image);}const title=document.createElement("div");title.className="art-title";title.textContent=card.title;title.style.left=`${card.x}%`;title.style.top=`${card.y}%`;title.style.fontSize=`${card.size/3.75}cqw`;node.append(title);const brand=document.createElement("span");brand.className="art-brand";brand.textContent=state.identity||"YAPARO · ÖRNEK ÇİZİM";brand.style.borderBottom=`3px solid ${state.accent}`;node.append(brand);if(editor)enableDrag(node,title);return node;}
function button(text,action,className=""){const el=document.createElement("button");el.type="button";el.textContent=text;el.className=className;el.addEventListener("click",action);return el;}
function renderCards(){const root=$("concepts");root.replaceChildren();state.cards.forEach(card=>{const section=document.createElement("article");section.className=`concept-card ${state.selected===card.id?"selected":""}`;section.append(art(card));const info=document.createElement("div");info.className="concept-info";const title=document.createElement("h2");title.textContent=approachNames[card.kind];const body=document.createElement("p");body.textContent=card.body;const actions=document.createElement("div");actions.className="card-actions";const choose=button(state.selected===card.id?"✓ Seçildi":"Bununla devam et",()=>{state.selected=card.id;renderCards();toast("İçeriğin seçildi. Düzenleyebilir veya planına geçebilirsin.");},"choose");choose.setAttribute("aria-pressed",String(state.selected===card.id));actions.append(choose,button("Düzenle",()=>openEditor(card),"quiet"),button("Benzerini gör",()=>{rememberEdit(card);card.variant++;card.title=card.variant%2?"Yeni bir detay.\nAynı güzel his.":sampleTitles()[card.kind];renderCards();toast("Aynı görsel dilde sabit örnek alternatif gösterildi. AI üretimi yapılmadı.");},"quiet"));if(card.edits.length)actions.append(button("Son düzenlemeyi geri al",()=>{Object.assign(card,card.edits.pop());renderCards();},"quiet"));info.append(title,body,actions);section.append(info);root.append(section);});$("content-next").disabled=!state.selected;$("batch-status").textContent=`Örnek grup ${state.batch} · Üretim ücreti yok`;$("previous-batch").disabled=!state.history.length;}
$("regenerate").addEventListener("click",()=>{makeBatch();go(1);message("Yeni bir örnek üçlü gösterdim. Önceki üçlüye dönerek eski seçimini ve düzenlemelerini bulabilirsin. Ücretli akışta yeniden üretim bedeli önce gösterilecek.");});
const previous=button("← Önceki üçlü",()=>{const last=state.history.pop();if(!last)return;Object.assign(state,last);state.unlocked=1;state.plan=null;$("brief").value=state.brief;$("brief-summary").textContent=state.brief;renderCards();go(1);},"quiet");previous.id="previous-batch";previous.disabled=true;$("regenerate").after(previous);
$("content-next").addEventListener("click",()=>{if(!state.selected)return;state.unlocked=Math.max(2,state.unlocked);go(2);message("Seçtiğin içeriği korudum. Şimdi hedefini ve bütçeni netleştirelim. Buradaki kanal dağılımı yalnız örnek bir öneri.");});
$("identity-open").addEventListener("click",()=>$("identity-dialog").showModal());
$("identity-save").addEventListener("click",()=>{state.identity=$("identity-name").value.trim();state.tone=$("tone").value;state.accent=$("accent").value;$("identity-open").textContent=state.identity?`◈ ${state.identity}`:"◈ Kimlik ve tarz";$("identity-dialog").close();if(state.cards.length)renderCards();if(state.step===3)review();message(`${state.identity||"Geçici tarz"} · ${state.tone}. Ad ve vurgu rengi örnek kartlara uygulandı. Ton tercihi saklandı; bu taslak metinleri AI ile yeniden üretmez.`);});
function rememberEdit(card){card.edits.push({title:card.title,body:card.body,x:card.x,y:card.y,size:card.size,variant:card.variant});if(card.edits.length>50)card.edits.shift();}
function openEditor(card){state.editing={...card};$("edit-title").value=card.title;$("edit-body").value=card.body;$("edit-x").value=card.x;$("edit-y").value=card.y;$("edit-size").value=card.size;renderEditor();$("editor-dialog").showModal();}
function renderEditor(){$("editor-art").replaceChildren(art(state.editing,true));}
["edit-title","edit-body","edit-x","edit-y","edit-size"].forEach(id=>$(id).addEventListener("input",()=>{state.editing.title=$("edit-title").value;state.editing.body=$("edit-body").value;state.editing.x=Number($("edit-x").value);state.editing.y=Number($("edit-y").value);state.editing.size=Number($("edit-size").value);renderEditor();}));
function enableDrag(stage,title){title.addEventListener("pointerdown",event=>{title.setPointerCapture(event.pointerId);const rect=stage.getBoundingClientRect();const dx=event.clientX-rect.left-state.editing.x*rect.width/100;const dy=event.clientY-rect.top-state.editing.y*rect.height/100;title.onpointermove=e=>{if(!title.hasPointerCapture(e.pointerId))return;state.editing.x=Math.max(5,Math.min(30,(e.clientX-rect.left-dx)*100/rect.width));state.editing.y=Math.max(8,Math.min(65,(e.clientY-rect.top-dy)*100/rect.height));title.style.left=`${state.editing.x}%`;title.style.top=`${state.editing.y}%`;$("edit-x").value=state.editing.x;$("edit-y").value=state.editing.y;};title.onpointerup=e=>{title.releasePointerCapture(e.pointerId);title.onpointermove=null;};});}
$("editor-save").addEventListener("click",()=>{if(!state.editing.title.trim()){toast("Başlık boş kalmasın.");return;}const index=state.cards.findIndex(c=>c.id===state.editing.id);rememberEdit(state.cards[index]);state.cards[index]={...state.editing};state.selected=state.editing.id;renderCards();$("editor-dialog").close();toast("Düzenlemen bu sekmedeki içeriğe uygulandı. Aynı akıştasın.");});
$("editor-cancel").addEventListener("click",()=>$("editor-dialog").close());
$("reference").addEventListener("change",async()=>{const version=++fileVersion;const file=$("reference").files[0];if(!file)return;if(!["image/png","image/jpeg"].includes(file.type)||file.size>5*1024*1024){toast("En fazla 5 MB sentetik PNG veya JPEG seç.");$("reference").value="";return;}const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();if(version!==fileVersion){URL.revokeObjectURL(url);return;}if(img.naturalWidth*img.naturalHeight>16000000)throw Error();if(state.image)URL.revokeObjectURL(state.image);state.image=url;$("reference-preview").querySelector("img").src=url;$("reference-preview").hidden=false;$("reference-status").textContent="Görsel yalnız sekmende · Sunucuya yüklenmez";if(state.cards.length)renderCards();toast("Yerel görsel önizlemeye eklendi. AI ile işlenmedi.");}catch{URL.revokeObjectURL(url);if(version===fileVersion)toast("Görsel açılamadı veya çok büyük. Daha küçük bir PNG/JPEG seç.");}finally{if(version===fileVersion)$("reference").value="";}});
$("remove-reference").addEventListener("click",()=>{fileVersion++;if(state.image)URL.revokeObjectURL(state.image);state.image=null;$("reference-preview").hidden=true;$("reference-preview").querySelector("img").removeAttribute("src");$("reference-status").textContent="İsteğe bağlı · Yalnız sentetik PNG/JPEG";if(state.cards.length)renderCards();});
const tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+1);const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;$("start").value=iso(tomorrow);$("start").min=iso(new Date());
function allocation(){YaparoGeo.update();}
$("budget").addEventListener("input",allocation);$("duration").addEventListener("input",allocation);$("goal").addEventListener("change",allocation);allocation();
function invalidatePlan(){if(!state.plan)return;state.plan=null;state.unlocked=Math.min(2,state.unlocked);document.querySelectorAll(".progress button")[3].disabled=true;$("finish").disabled=true;$("finish-status").textContent="Plan değişti; yeni özeti tekrar oluştur.";}
$("plan-form").addEventListener("input",invalidatePlan);
$("plan-form").addEventListener("change",invalidatePlan);
document.addEventListener("yaparo-geography-change",invalidatePlan);
$("plan-form").addEventListener("submit",event=>{event.preventDefault();if(!state.selected)return;const geography=YaparoGeo.snapshot();if(!geography){toast("Konum ve yarıçap alanlarını kontrol et. Sınırlar kendiliğinden genişletilmez.");return;}state.plan={geo:geography,goal:$("goal").selectedOptions[0].textContent,region:geography.label,audience:$("audience").value.trim(),destination:$("destination").value.trim(),budget:Number($("budget").value),start:$("start").value,days:Number($("duration").value),google:Number($("google").value)};if(!state.plan.region||!state.plan.audience||!state.plan.destination){toast("Bölge, hedef kitle ve sonraki adımı doldur.");return;}state.unlocked=3;go(3);message("Seçtiğin içerik, kanal payları ve bütçen özette. Bu taslak hiçbir hesabı bağlamaz, reklam yayımlamaz veya ödeme almaz.");});
function review(){if(!state.plan||!state.selected)return;const p=state.plan,card=state.cards.find(c=>c.id===state.selected);$("final-creative").replaceChildren(art(card));const dl=$("review-values");dl.replaceChildren();const end=new Date(`${p.start}T12:00:00`);end.setDate(end.getDate()+p.days-1);const dateLabel=value=>new Intl.DateTimeFormat("tr-TR").format(new Date(`${value}T12:00:00`));const pairs=[["Kimlik ve tarz",state.identity||"Bu çalışmaya özel geçici tarz"],["İstek",state.brief],["Seçilen yaklaşım",approachNames[card.kind]],["Başlık",card.title],["Açıklama",card.body],["Hedef",p.goal],["Bölge ve kitle",`${p.region} · ${p.audience}`],["Sonraki adım",p.destination],["Tarih",`${dateLabel(p.start)} – ${dateLabel(iso(end))} · ${p.days} gün`],["Coğrafi seçim",p.geo.label],["Kullanıcının seçtiği senaryo payları",p.geo.channels.map(c=>`${c.name} %${c.share.toFixed(1)} · ${money(c.amountCents/100)}`).join(" · ")],["Tamamen varsayımsal hesap",p.geo.channels.map(c=>`${c.name}: ≈${Math.floor(c.impressions)} gösterim / ≈${Math.floor(c.clicks)} tıklama`).join(" · ")],["Türkiye kapsamı",p.geo.areaKm2==null?"Bölge sınırı çözümü bekliyor":`Yaklaşık ${Math.round(p.geo.areaKm2)} km² · Türkiye dışı hariç`],["Senaryo varsayımları",`CPM ${p.geo.assumptions.cpm} TRY · CTR %${p.geo.assumptions.ctr} · yoğunluk ${p.geo.assumptions.density}/km² · tekrar ${p.geo.assumptions.frequency}; gerçek tahmin değildir`],["Pay ayrılmayan kanallar",p.geo.exclusions],["Doğrulama durumu","Yalnız konum türü desteği incelendi; gerçek hesap ve içerik uygunluğu bekliyor."]];pairs.forEach(([key,value])=>{const dt=document.createElement("dt"),dd=document.createElement("dd");dt.textContent=key;dd.textContent=value;dl.append(dt,dd);});$("review-budget").textContent=money(p.budget);$("finish-status").textContent="";$("finish").disabled=false;}
$("finish").addEventListener("click",()=>{$("finish-status").textContent="Deneyim tamamlandı. Tercihlerin bu sekmede duruyor; kalıcı kayıt, ödeme veya reklam yayını yapılmadı.";$("finish").disabled=true;});
function chat(text){message(text,true);const lower=text.toLocaleLowerCase("tr-TR");if(lower.includes("kanal")||lower.includes("bütçe")){message("Konum türü desteği doğrulanmayan kanalların payı %0. Yarıçap seçimi 1–800 km aralığında; Google ve Microsoft yarıçap türü için coğrafi aday. İstediğin uygun kanalı seçip önceliğini ayarlayabilirsin. Meta yarıçap sınırı doğrulanmadı; diğer kanalların durumunu katalogda görebilirsin. Rakamlar yalnız açık örnek varsayımlarla senaryo hesabıdır. Bu taslakta hesap/içerik uygunluğu veya performans kanıtı yok. Alanını sessizce büyütmeyiz.");}else if(lower.includes("sade")){const selected=state.cards.find(c=>c.id===state.selected);if(selected){openEditor(selected);message("Seçtiğin içeriği düzenleme alanında açtım. Metni ve konumu değiştirebilirsin; uygulamadan önce önizle. Otomatik AI düzenlemesi yapılmadı.");}else message("Sade bir yön istediğini not ettim. İçerik aşamasında önce bir seçenek seç; ardından birlikte düzenleyelim. Bu örnek yardımcı serbest metinle AI üretimi yapmaz.");}else if(lower.includes("görsel")||lower.includes("resim")){message("İsteğini anlat aşamasındaki Görsel ekle düğmesiyle sentetik bir PNG/JPEG seçebilirsin. Yalnız kendi tarayıcında önizlenir, hiçbir sağlayıcıya gönderilmez.");}else{message(state.step===0?"Mesajını bu çalışmada görüyorum. Üretim isteğini soldaki alana yazıp Üç yaklaşımı keşfet ile ilerleyebilirsin. Bu yardımcı henüz gerçek bir dil modeli değil.":`Şu an ${["istek","içerik seçimi","kampanya planı","son kontrol"][state.step]} aşamasındasın. ${state.selected?"İçerik seçimin korunuyor.":"Bir yaklaşım seçebilir veya düzenleyebilirsin."} Serbest komutların uygulanması gerçek AI entegrasyonu sonrası gelecek.`);}}
$("chat-form").addEventListener("submit",event=>{event.preventDefault();const text=$("chat-input").value.trim();if(!text)return;chat(text);$("chat-input").value="";});document.querySelectorAll("[data-chat]").forEach(el=>el.addEventListener("click",()=>chat(el.dataset.chat)));

$("reference-open").addEventListener("click",()=>$("reference").click());
$("helper-toggle").addEventListener("click",()=>{const open=document.querySelector(".assistant").classList.toggle("mobile-open");$("helper-toggle").setAttribute("aria-expanded",String(open));$("helper-toggle").textContent=open?"Yardımcıyı kapat ✕":"✳ Yardımcı";if(open)$("chat-input").focus();});
